import java.text.DecimalFormat;
import java.util.Scanner;
public class JAverage {
	public static void main(String[] args) {
		//Khatwa 1: Tarif al-mutaghayyirat allati nahtaajuha lihadha al-barnamaj
		int total = 0;
		int count = 0;
		double average;
		//Khatwa 2: Qra al-aadad al-awwal alladhi yadkhuluhu al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhul adad kamil (0 lilkhorug): ");
		int num = scan.nextInt();
		//Khatwa 3: Aalij al-aadad alladhi adkhalahu al-mustakhdim, thumma istalam wa aalij al-aadad al-muqbila ma dumma anna al-mustakhdim yadkhul adadan ghair sifr; wila dhalik tawqif
		while (num != 0) {
			count++;
			total += num;
			System.out.println("Al-majmu hatta al-aan huwa " + total+", al-adad = "+count);
			System.out.println("Adkhul adad kamil (0 lilkhorug): ");
			num = scan.nextInt();   
		}
		scan.close();
		//Khatwa 4: Hisaab wa tabea mutawassit al-aadad al-mudkhalah min al-mustakhdim
		if (count == 0) {
			System.out.println("Lam yadkhul ay a'adad.");
		} else {
			average = (double) total / count;
			DecimalFormat fmt = new DecimalFormat("0.###");
			System.out.println("Al-muaddal huwa " + fmt.format(average));
		}
	}
}
